import type { IndividualMatch } from "../types";
import type { Spielbericht } from "../utils/spielbericht";

// ── Spielberichte, direkt aus dem btv.de-Widget gecrawlt ─────────────────────
// AUTO-GENERIERT von scripts/generate-spielberichte.mjs (npm run gen:spielberichte)
// auf Basis von scripts/crawl-spielberichte.mjs — NICHT von Hand editieren.
// Stand: 06.10.2026.
// Enthält alle in nuLiga sichtbaren Begegnungen der Saisons Sommer 2026 (1324), Winter 2025/26 (572), Sommer 2025 (1187), Winter 2024/25 (534)
// — 3617 Berichte. Jeder Bericht trägt seine Saison, weil sich
// Gruppennummern über die Jahre wiederholen. Handgepflegte Berichte in
// spielberichte.ts greifen nur für Begegnungen, die hier fehlen (z. B.
// gestrichene Spiele zurückgezogener Mannschaften).

function m(
  id: string,
  position: number,
  type: "singles" | "doubles",
  home: string,
  away: string,
  sets: Array<[number, number]>,
  winner: "home" | "away",
): IndividualMatch {
  return {
    id,
    match_score_id: id.split("-")[0],
    position,
    match_type: type,
    home_player: home,
    away_player: away,
    set1_home: sets[0]?.[0] ?? null,
    set1_away: sets[0]?.[1] ?? null,
    set2_home: sets[1]?.[0] ?? null,
    set2_away: sets[1]?.[1] ?? null,
    set3_home: sets[2]?.[0] ?? null,
    set3_away: sets[2]?.[1] ?? null,
    winner,
  };
}

// Jeder Bericht läuft durch r(): So ist jedes Element bereits als Spielbericht
// typisiert, und TypeScript muss nicht aus Tausenden Objektliteralen einen
// Vereinigungstyp bilden (ab ~2.500 Berichten: TS2590 „union type too complex").
const r = (b: Spielbericht): Spielbericht => b;

